/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/menu/content.md
 */
export const MenuCheckboxItemIndicator = ({
  children,
  className,
  ...props
}: MenuCheckboxItemIndicatorProps) => {
  const { slots } = useMenuContext();
  return (
    <BaseMenu.CheckboxItemIndicator
      className={cn(slots.checkboxItemIndicator(), className)}
      {...props}
    >
      {children ?? (
        <svg className="h-4 w-4 stroke-current" fill="none" strokeWidth="2" viewBox="0 0 24 24">
          <polyline points="20 6 9 17 4 12" />
        </svg>
      )}
    </BaseMenu.CheckboxItemIndicator>
  );
};

export type MenuRadioGroupProps = React.ComponentProps<typeof BaseMenu.RadioGroup>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/menu/content.md
 */
export const MenuRadioGroup = ({ className, ...props }: MenuRadioGroupProps) => {
  const { slots } = useMenuContext();
  return <BaseMenu.RadioGroup className={cn(slots.radioGroup(), className)} {...props} />;
};

export type MenuRadioItemProps = React.ComponentProps<typeof BaseMenu.RadioItem>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/menu/content.md
 */
export const MenuRadioItem = ({ className, ...props }: MenuRadioItemProps) => {
  const { slots } = useMenuContext();
  return <BaseMenu.RadioItem className={cn(slots.radioItem(), className)} {...props} />;
};

export type MenuRadioItemIndicatorProps = React.ComponentProps<typeof BaseMenu.RadioItemIndicator>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/menu/content.md
 */
export const MenuRadioItemIndicator = ({
  children,
  className,
  ...props
}: MenuRadioItemIndicatorProps) => {
  const { slots } = useMenuContext();
  return (
    <BaseMenu.RadioItemIndicator className={cn(slots.radioItemIndicator(), className)} {...props}>
      {children ?? (
        <svg className="h-2 w-2 fill-current" viewBox="0 0 8 8">
          <circle cx="4" cy="4" r="4" />
        </svg>
      )}
    </BaseMenu.RadioItemIndicator>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const menuVariants = tv({
  slots: {
    root: "menu",
    trigger: "menu__trigger",
    positioner: "menu__positioner",
    popup: "menu__popup",
    item: "menu__item",
    separator: "menu__separator",
    submenuTrigger: "menu__submenu-trigger",
    group: "menu__group",
    groupLabel: "menu__group-label",
    checkboxItem: "menu__checkbox-item",
    checkboxItemIndicator: "menu__checkbox-item-indicator",
    radioGroup: "menu__radio-group",
    radioItem: "menu__radio-item",
    radioItemIndicator: "menu__radio-item-indicator",
  },
  variants: {
    size: {
      sm: {
        popup: "menu__popup--sm",
        item: "menu__item--sm",
      },
      md: {
        popup: "menu__popup--md",
        item: "menu__item--md",
      },
      lg: {
        popup: "menu__popup--lg",
        item: "menu__item--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type MenuVariants = VariantProps<typeof menuVariants>;

"use client";

import { createContext, useContext } from "react";

import { menuVariants } from "./menu.variants";

export type MenuContext = {
  slots: ReturnType<typeof menuVariants>;
};

export const MenuContext = createContext<MenuContext | null>(null);

export const useMenuContext = () => {
  const context = useContext(MenuContext);
  return context ?? { slots: menuVariants() };
};

.menu__positioner {
  @apply outline-none z-50;
}

.menu__popup {
  @apply min-w-44 overflow-hidden rounded-md border border-border bg-popover py-1 text-popover-foreground shadow-md transition-all duration-100 ease-out data-ending-style:scale-95 data-ending-style:opacity-0 data-starting-style:scale-95 data-starting-style:opacity-0;
}

.menu__item {
  @apply relative flex cursor-default select-none items-center justify-between rounded-xs px-2 py-1.5 text-sm text-foreground outline-none transition-colors data-highlighted:bg-accent data-highlighted:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50;
}

.menu__separator {
  @apply -mx-1 my-1 h-px bg-border;
}

.menu__submenu-trigger {
  @apply relative flex cursor-default select-none items-center justify-between rounded-xs px-2 py-1.5 text-sm text-foreground outline-none transition-colors data-highlighted:bg-accent data-highlighted:text-accent-foreground data-popup-open:bg-accent data-popup-open:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50;
}

.menu__group-label {
  @apply px-2 py-1.5 text-xs font-semibold text-muted-foreground;
}

.menu__checkbox-item,
.menu__radio-item {
  @apply relative flex cursor-default select-none items-center gap-2 rounded-xs px-2 py-1.5 text-sm text-foreground outline-none transition-colors data-highlighted:bg-accent data-highlighted:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50;
}

.menu__checkbox-item-indicator,
.menu__radio-item-indicator {
  @apply flex size-4 items-center justify-center shrink-0 text-foreground;
}
